transforms.code:
	system.perspective.print("checkFormula() called") 	

	chkShtId = self.view.custom.value.chkShtId
	chkItemId = self.view.custom.value.chkItemId
	formula = value.formula	
	formulaType = value.formulaType
	testValue = 5.0
	valuesList = []	

	if formulaType is None: return {'chkOk':False, 'value': None, 'msg':'No formula type set'}

	#We need to pull out the checkname values and replace them with actual values to be able to test
	checkData = system.kanoa.quality.config.getChecks({'chkShtId':chkShtId})
	chkItemList = [checkData.getValueAt(i, 'chkItemGroupName') + '\\' + checkData.getValueAt(i, 'chkItemName') for i in range(checkData.rowCount)]	

	if formulaType == 'SCRIPT':
		func = value.script
		if func is None: return {'chkOk':False, 'value': None, 'msg':"No script selected"}
		args = {'chkShtInfo': self.custom.chkShtInfo}
		if formula:
			measurements = {}
			i = 0
			for chkName in chkItemList:
				if 	"'" + chkName + "'" in formula:	#checkNames are wrapped with quotes in the formula so that find the exact check name and not 'M3' in 'M3A'
					i += 1
					testValue += 0.12
					measurements[str(i)] = testValue
			args['measurements'] = measurements
		system.perspective.print("script args %s"%args)
		retVal, msg = kanoaScripts.custom.quality.calculators.executeCalculator(func, args)
#		return {'chkOk':msg is None, 'value': str(retVal), 'msg': msg}
		return {'chkOk':True, 'value': str(retVal), 'msg': msg}

	if formula is None: return {'chkOk':False, 'value': None, 'msg':'No formula set'}
	if '__import__' in value.formula: return {'chkOk':False, 'value': None, 'msg':"Formula is dangerous. What are you trying to do here?"}

	for chkName in chkItemList:
		chkName = "'" + chkName + "'"
		if chkName in formula:
			testValue += 1.0
			formula = formula.replace(chkName, str(float(testValue)))

	if formulaType == 'EVAL':	
		if "," in formula: return {'chkOk':False, 'msg':"Formula contains a comma (%s)"%formula}
		try:
			calcValue = eval(formula)
			return {'chkOk':True, 'value': str(calcValue), 'msg':"Formula = " + formulaType + "(" + str(formula) + ") returns " + str(calcValue)}
		except:
			return {'chkOk':False, 'value': None, 'msg':"Formula = " + str(formula) + " returns error"}

	#This is for all other calculation types such as AVG, SUM etc.
	try:
		calcValue = None
		formula = formula.split(",")
		formula = [float(formula[i]) for i in range(len(formula))]

		if formulaType == 'AVG':calcValue = system.math.mean(formula)
		elif formulaType == 'STDDEV':	calcValue = system.math.standardDeviation(formula)
		elif formulaType == 'SUM': calcValue = system.math.sum(formula)					
		elif formulaType == 'MIN':	 calcValue = system.math.min(formula)
		elif formulaType == 'MAX': calcValue = system.math.max(formula)
		elif formulaType == 'RANGE': calcValue = system.math.max(formula) - system.math.min(formula)

		return {'chkOk':True, 'value': str(calcValue), 'msg':"Formula = " + formulaType + "(" + str(formula) + ") returns " + str(calcValue)}
	except:
		return {'chkOk':False, 'value': None, 'msg':'Error in the formula (%s)'%formula}

	return {'chkOk':False, 'value': None, 'msg':'Unknown error'}

if value is not None: 
	calculation = system.util.jsonDecode(value)
	return {"formulaType": calculation['formulaType'], "script": calculation['script'], "formula": calculation['values']}
else: return {'formulaType': None, 'script': None, 'formula': None}

paramsDict = {'chkShtId': value['chkShtId']}
if value['calcInfo']['formulaType'] != 'SCRIPT': paramsDict['isNumeric'] = True
return system.kanoa.quality.config.getChecks(paramsDict)

